const parashot=[
{id:'reeh',name:'ראה',number:'פרשה מ״ז',book:'דברים',date:'ב׳ באלול תשפ״ו',thesis:'לפני שאנחנו בוחרים — אנחנו צריכים ללמוד לראות.',topics:['בחירה','מנהיגות','חיים','כסף','אחריות'],question:'איזו החלטה בחיים שלי אני כבר יודע עמוק בפנים מה נכון לעשות לגביה — אבל עדיין לא בוחר לעשות אותה?',sections:[['מה קורה בפרשה?','משה מציב בפני עם ישראל את הברכה ואת הקללה. הוא מצווה על השמדת העבודה הזרה, על ריכוז עבודת ה׳ במקום אשר יבחר, ומפרט דיני כשרות, מעשרות, שמיטת כספים, צדקה, עבד עברי ושלושת הרגלים. הנושאים רבים, אבל עובר ביניהם חוט אחד: איך אדם וחברה בוחרים את דרכם כאשר עומדות בפניהם אפשרויות שונות.'],['“ראה אנוכי נותן לפניכם”','הפרשה נפתחת בלשון יחיד — “ראה” — ומיד עוברת ללשון רבים: “לפניכם”. אפשר לראות בכך מסר כפול. הבחירה היא אישית, אך התוצאות שלה אינן נשארות פרטיות. החלטה של מנהל משפיעה על עובדים; החלטה של הורה מעצבת משפחה; החלטות קטנות של יחידים יוצרות בסופו של דבר תרבות שלמה.'],['מדוע הפרשה נקראת “ראה” ולא “בחר”?','לפני שאנחנו משנים החלטות, אנחנו צריכים לשנות את האופן שבו אנחנו רואים את המציאות. הבחירה מתחילה במסגרת שדרכה אנחנו מפרשים את העולם: למה אנחנו שמים לב, מה אנחנו מגדירים כהצלחה, ואיזה מחיר אנחנו כלל לא רואים. לכן התורה אינה מתחילה בציווי לבחור — אלא בהזמנה לראות.'],['ברכה וקללה אינן תמיד מסומנות','“את הברכה אשר תשמעו... והקללה אם לא תשמעו”. בטווח הקצר, הברכה אינה תמיד מרגישה כברכה והקללה אינה תמיד נראית כקללה. ויתור, משמעת, אמת לא נעימה או השקעה ארוכת טווח יכולים להיות קשים עכשיו וטובים אחר כך. מנגד, דרך קלה ומהירה יכולה לגבות מחיר שרואים רק מאוחר יותר.'],['הבחירות הקשות באמת','בדרך כלל איננו בוחרים בין משהו שמסומן בבירור “טוב” לבין משהו שמסומן “רע”. הבחירות הקשות באמת הן: נוח מול נכון; מיידי מול ארוך טווח; אגו מול מערכת יחסים; רווח אישי מול אחריות לאחר; ומה שנראה טוב עכשיו מול מה שיהיה טוב בעוד חמש שנים.'],['“פתח תפתח את ידך”','בתוך פרשה שעוסקת בבחירה מופיעה מצוות הצדקה. התורה מכירה בתנועה הטבעית של היד להיסגר סביב מה ששייך לנו, ולכן היא חוזרת ואומרת “פתח תפתח”. נדיבות אינה רק העברת כסף; היא בחירה שלא לתת לפחד ממחסור לנהל את כל היחסים שלנו עם האחר.'],['כסף, שמיטה והיכולת לשחרר','שמיטת הכספים מזכירה שמערכת כלכלית אינה יכולה להישען רק על חוזים וחובות; היא זקוקה גם למנגנון שמאפשר לאדם לקום מחדש. זהו מתח אמיתי בין אחריות כלכלית לבין חמלה. חברה בריאה אינה מבטלת אחריות, אך גם אינה הופכת טעות או קושי לגזר דין לכל החיים.'],['החיבור להצלחה ולמנהיגות','מנהל נדרש שוב ושוב לבחור בין היעד המיידי לבין בניית צוות לטווח ארוך, בין ניצחון בוויכוח לבין שמירת מערכת היחסים, ובין עסקה טובה על הנייר לבין הדרך שבה הושגה. פרשת ראה מזכירה שהמדד אינו רק מה השגנו, אלא גם איזו דרך בנינו בדרך אל ההישג.'],['התובנה שאני לוקח מפרשת ראה','החיים הם במידה רבה תוצאה של בחירות, אבל הבחירות הן תוצאה של הראייה שלנו. מי שרואה רק את הרגע הנוכחי יבחר אחרת ממי שרואה את המחיר העתידי; מי שרואה רק את עצמו יבחר אחרת ממי שרואה גם את האנשים סביבו. לכן השינוי מתחיל בשאלה: מה אני עדיין לא רואה?']]},
{id:'ki-tetze',name:'כי־תצא',number:'פרשה מ״ט',book:'דברים',date:'ט׳ באלול תשפ״ו',thesis:'האופי שלנו נבנה מהחלטות קטנות שאף אחד כמעט לא רואה.',topics:['אחריות','ניהול','מוסר','משפחה','אלול'],question:'איפה בחיים שלי אני אומר לעצמי “זה קטן, זה לא באמת משנה” — כשבעצם דווקא שם נבחן האדם שאני רוצה להיות?',sections:[['איך נראים ערכים כשהם פוגשים את החיים עצמם?','לפי מניין הרמב״ם יש בפרשה 72 מצוות — יותר מבכל פרשה אחרת בתורה. דווקא ריבוי הנושאים מגלה את הרעיון הגדול שלה: התורה אינה אמורה להישאר בבית הכנסת. היא נכנסת למלחמה, לבית, לזוגיות, לעסקים, לכסף, ליחסי עובד–מעביד, לאחריות כלפי הזולת ואפילו לאופן שבו בונים גג.'],['מה קורה בפרשה?','הפרשה נפתחת בדין אשת יפת תואר וממשיכה בדיני ירושה ובן סורר ומורה; השבת אבדה; עזרה לבהמה שקרסה; שילוח הקן; בניית מעקה לגג; איסור שעטנז; דיני נישואין וגירושין; הגנה על החלש; תשלום שכר בזמן; השארת חלק מהיבול לעני, לגר, ליתום ולאלמנה; מידות ומשקלות הוגנים; ולבסוף זכירת עמלק. המדרש מסכם: לכל מקום שתלך — המצוות מלוות אותך.'],['הרעיון הגדול: המבחן נמצא בפרטים הקטנים','קל להיות אדם ערכי ברמת ההצהרה. כי־תצא שואלת שאלה קשה יותר: איך אתה מתנהג כשאף אחד לא מסתכל? אתה רואה אבדה ברחוב ויכול להמשיך. התורה אינה מסתפקת ב“השב תשיבם”, אלא אומרת “לא תוכל להתעלם” — היא מטפלת ביכולת לראות בעיה ולהחליט שהיא לא שלנו.'],['“ועשית מעקה לגגך” — אחריות לפני האסון','“כי תבנה בית חדש ועשית מעקה לגגך ולא תשים דמים בביתך”. אל תחכה שמישהו ייפול ואז תשאל מי אשם. זהה מראש את הסיכון ובנה מנגנון שמונע אותו. מנהל טוב אינו רק מי שמכבה שריפות היטב; הוא בונה מערכות שבהן חלק מהשריפות אינן פורצות מלכתחילה. גם במשפחה אפשר לבנות “מעקה” — שיחה, גבולות, חלוקת אחריות או הרגל אחר.'],['מנהיגות מתחילה במקום שאין בו הגדרת תפקיד','יש הבדל בין סמכות לאחריות. סמכות אומרת: זה בתחום האחריות שלי. אחריות אומרת: אולי זה אינו בתחום שלי, אבל ראיתי שמשהו לא בסדר ואני יכול לעזור. אנשים שאנחנו זוכרים כמנהיגים הם בדרך כלל מהסוג השני. השאלה הארגונית היא האם עובד שרואה בעיה במחלקה אחרת יתעלם, או ירים יד וינסה לתקן.'],['“ביומו תתן שכרו” — לראות את הצד השני','התורה מצווה לשלם לשכיר בזמן: “ביומו תתן שכרו... כי עני הוא ואליו הוא נושא את נפשו”. מבחינת המעסיק זה עוד תשלום; מבחינת העובד זה אולי שכר הדירה או הקניות למשפחה. אותה החלטה נראית אחרת משני צדי השולחן, ומנהיגות דורשת לעבור מדי פעם לצד השני.'],['מה עושה כאן “יפת תואר”?','חז״ל אומרים: “לא דיברה תורה אלא כנגד יצר הרע”. התורה אינה מתארת אדם אידיאלי שאין לו יצרים; היא פוגשת אדם אמיתי ומנסה ליצור גבולות גם כשהרגש חזק. העיקרון המעשי הוא לא לבנות את החיים על ההנחה שתמיד יהיה לנו כוח רצון, אלא לבנות מנגנונים שיעזרו גם כשהוא חלש — בכסף, בזמן, בתזונה, בזוגיות ובקבלת החלטות.'],['“ותן חלקנו” ואלול','תוכן של “ותן חלקנו” מחבר את “ובכתה את אביה ואת אמה ירח ימים” לחודש אלול, זמן של התעוררות, חשבון נפש והתקרבות. הפרשה אינה דורשת להפוך לאדם אחר ביום אחד; היא מציגה עשרות פעולות קטנות שבהן אפשר להיות קצת יותר טוב: להחזיר אבדה, לשלם בזמן, לא לנצל חולשה, לבנות מעקה, להשאיר לעני ולשלוט בדחף רגעי.'],['כוחה של עין יפה','במאמר נוסף של “ותן חלקנו” מופיע החיבור בין לשון הרע לבין היכולת להסתכל בעין יפה. הדרך שבה אנו מפרשים אדם אחר קודמת פעמים רבות לדרך שבה נדבר עליו. תיקון הדיבור מתחיל לעיתים בתיקון המבט.'],['התובנה שאני לוקח מפרשת כי־תצא','בשבוע שלפניה, פרשת שופטים עסקה בבניית המערכת — שופטים, מלך, נביא ומשפט. כי־תצא עוברת מהמוסדות אל האדם הבודד. האופי שלנו אינו נקבע בעיקר ברגעים הגדולים; הוא נבנה ממאות החלטות קטנות: איך דיברנו למלצר, האם החזרנו כסף שקיבלנו בטעות, איך הגבנו לעובד שטעה, האם קיימנו הבטחה לילד והאם עצרנו את עצמנו כשכעסנו.']]},
{id:'ki-tavo',name:'כי־תבוא',number:'פרשה נ׳',book:'דברים',date:'ט״ז באלול תשפ״ו',thesis:'הצלחה אמיתית היא לא רק להגיע למקום שרצית — אלא לא לאבד בדרך את היכולת להעריך שהגעת אליו.',topics:['הכרת הטוב','הצלחה','משפחה','ניהול','אלול'],question:'מה יש לי היום שפעם מאוד רציתי להשיג — וכבר התחלתי להתייחס אליו כמובן מאליו?',sections:[['לדעת לעצור ולהכיר בטוב','אם בפרשת כי־תצא עסקנו בשאלה איך הערכים שלנו מתבטאים בעשרות החלטות קטנות, כי־תבוא מוסיפה שלב עמוק יותר: מה קורה לאדם אחרי שהוא כבר הצליח? זו פרשה מרתקת להבנת הצלחה, הכרת הטוב והסכנה שבהתרגלות לשפע.'],['מה קורה בפרשה?','משה מתאר את הרגע שבו עם ישראל כבר יהיה בארץ, יעבד את האדמה ויראה את פירותיה. אז מגיעה מצוות הביכורים: לקחת מראשית הפרי, להניח אותו בטנא, לעלות לבית המקדש ולהודות. האדם מספר “ארמי אובד אבי” — הירידה למצרים, השעבוד, הצעקה, היציאה וההגעה לארץ. בהמשך מופיעים מעשרות, הברית, כתיבת התורה על אבנים, הברכה והקללה והתוכחה.'],['למה אדם שמביא כמה פירות צריך לספר את כל ההיסטוריה?','דמיין חקלאי שעובד שנים ולבסוף רואה תאנה ראשונה. האינסטינקט הטבעי שלו הוא “הצלחתי”. התורה אומרת: רגע. קח את הפרי הראשון וספר את הסיפור שהביא אותך לכאן. המאמץ שלך אמיתי, אבל אתה לעולם אינך הסיבה היחידה להצלחה. היו לפניך הורים, מורים, אנשים שנתנו הזדמנות, חברה, מדינה, היסטוריה, נסיבות — ובתפיסה הדתית גם הקב״ה.'],['דרך שלישית לדבר על הצלחה','יש שתי טעויות הפוכות: “הכול בזכותי”, ומנגד “שום דבר אינו בזכותי”. התורה מציעה דרך שלישית: עבדת קשה — היה גאה במה שעשית, אך אל תשכח את כל מה שקיבלת בדרך. זו ענווה שאינה מקטינה את האדם.'],['“ושמחת בכל הטוב”','התורה אינה רק אומרת “יש לך טוב”; היא אומרת: שים לב אליו ושמח בו. בית שרצינו, תפקיד שחיכינו לו, זוגיות, ילדים, עסק שהצליח ואפילו בריאות — המוח האנושי מסתגל במהירות לטוב. אפשר לקרוא את הביכורים כמנגנון נגד הסתגלות: פעם בשנה עצור, קח את הפרי, הסתכל עליו וזכור כמה דרך עברת.'],['“מרוב כל” — הסכנה שבשפע','בתוכחה מופיע הפסוק “תחת אשר לא עבדת את ה׳ אלוהיך בשמחה ובטוב לבב מרוב כל”. לא מדובר בהכרח באדם שאין לו; יש לו “רוב כל”, ובכל זאת הוא אינו שמח. בתחילת הפרשה נאמר “ושמחת בכל הטוב”, ובהמשך מתברר מה קורה כאשר יש לאדם הרבה אך הוא מאבד את היכולת לראות את הטוב.'],['ומה אומר כאן “ותן חלקנו”?','נמצא תוכן של “ותן חלקנו” סביב הפסוק “והיה אם שמוע תשמע” והרעיון שהחלק שאדם בונה לעצמו נוצר מתוך העבודה והעמל בעולם הזה. חשוב לשמור על ההבחנה: החיבור בין ביכורים, הצלחה והכרת הטוב הוא הפרשנות המוצעת כאן על בסיס פסוקי הפרשה, ולא רעיון שיוחס ישירות ל“ותן חלקנו”.'],['טקס הביכורים הארגוני','אחרי עסקה גדולה אפשר לומר “בניתי אסטרטגיה וסגרתי”, ואפשר גם לשאול מי עוד הביא אותנו לכאן: איש המכירות שפתח את הדלת, המהנדס שעשה את ההדגמה, הלקוח שנתן אמון, העובד שעבד בלילה והשותף שחיבר בינינו. מנהיג טוב יודע לקחת הצלחה ולשאול מי עוד צריך לקבל עליה תודה.'],['גם במשפחה','מערכות יחסים סובלות מהסתגלות. בתחילת זוגיות מבחינים בכל מחווה; אחרי שנים דברים רבים הופכים למובנים מאליהם. לפעמים צריך להביא “ביכורים” גם לאנשים ולומר: שמתי לב למה שעשית; אני מעריך את זה; אני יודע שזה לא מובן מאליו. שלושה משפטים קטנים יכולים לשנות מערכת יחסים.'],['חשבון נפש של חודש אלול','בדרך כלל חושבים על חשבון נפש כרשימת הדברים שעשינו לא טוב. כי־תבוא מציעה להתחיל בכיוון ההפוך: לפני שאתה בודק מה חסר, בדוק מה כבר יש. מה קיבלתי השנה? מה השתפר? מי נכנס לחיי? איפה הצלחתי? ממי למדתי? על מה אני רוצה לומר תודה? ורק אז — מה אני רוצה לתקן.'],['התובנה שאני לוקח מפרשת כי־תבוא','הביכורים מלמדים לעצור בתוך המרוץ, להסתכל על הפרי, לזכור מאין באנו, לזהות מי עזר לנו להגיע ולהכיר גם בחלק שלנו וגם במה שקיבלנו. האדם מביא דווקא את הפרי הראשון, לא את האחרון: התורה אינה אומרת “כשיהיה לך מספיק — אז תודה”, אלא “עוד לפני שאתה יודע כמה יהיה לך, למד להכיר תודה על מה שכבר צמח”.']]}
];
