for (const [index, parasha] of parashot.entries()) {
  const reading = expandedReadings[parasha.id];
  if (!reading) continue;

  const [summary, centralIdea, application] = parasha.sections;
  parashot[index] = {
    ...parasha,
    sections: [summary, centralIdea, ...reading.sections, application],
    sources: reading.sources,
    practice: reading.practice,
  };
}

const vayetzei = parashot.find(parasha => parasha.id === 'vayetzei');
vayetzei.thesis = 'איך בונים עתיד חדש כשאין לנו שליטה על כל מה שקורה בדרך?';
